{
  "diagnosis": "Batuk Pilek Umum (Common Cold) / Infeksi Saluran Pernapasan Akut (ISPA) ringan",
  "diagnosis_reasoning": "Gejala batuk, hidung meler, dan badan pegal-pegal yang timbul setelah kehujanan sangat konsisten dengan infeksi virus saluran pernapasan atas (common cold) yang umumnya ringan.",
  "follow_up_questions": [
    "Apakah Anda juga merasakan demam? Jika iya, berapa suhu badan Anda?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Gejala yang dilaporkan adalah umum dan ringan, tidak menunjukkan tanda bahaya yang memerlukan penanganan medis segera atau darurat."
}

{
  "diagnosis": "Konjungtivitis Bakterial Akut",
  "diagnosis_reasoning": "Gejala mata merah, gatal, serta adanya sekret (belek) yang banyak, kekuningan, dan menyebabkan mata lengket saat bangun tidur sangat mengindikasikan adanya infeksi bakteri pada konjungtiva.",
  "follow_up_questions": [
    "Apakah ada perubahan pada penglihatan Anda (misalnya kabur) atau nyeri pada mata?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala menunjukkan kemungkinan infeksi bakteri pada mata yang memerlukan evaluasi dan pengobatan untuk mencegah komplikasi atau penularan, namun tidak ada tanda kegawatdaruratan yang mengancam penglihatan secara langsung saat ini."
}

{
  "diagnosis": "Penyakit Refluks Gastroesofageal (GERD)",
  "diagnosis_reasoning": "Keluhan nyeri dada yang terasa panas seperti terbakar (heartburn), terutama setelah makan dan malam hari, disertai sensasi adanya sesuatu yang naik ke tenggorokan (regurgitasi) selama 2 minggu, sangat khas untuk Penyakit Refluks Gastroesofageal (GERD). Berat badan yang berlebih juga merupakan faktor risiko.",
  "follow_up_questions": [
    "Apakah Anda juga mengalami kesulitan menelan (disfagia) atau nyeri saat menelan (odinofagia)?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala sudah berlangsung selama 2 minggu dan mengganggu aktivitas sehari-hari (setelah makan dan malam hari), memerlukan evaluasi medis untuk penegakan diagnosis dan penatalaksanaan yang tepat guna mencegah komplikasi lebih lanjut. Meskipun tidak ada tanda-tanda kegawatdaruratan segera, kondisi ini membutuhkan perhatian medis profesional."
}

{
  "diagnosis": "Insomnia Akut",
  "diagnosis_reasoning": "Pasien mengalami kesulitan memulai tidur (insomnia onset) selama 4 hari yang menyebabkan gangguan fungsi di siang hari (sulit fokus, gampang emosi), sesuai dengan kriteria insomnia akut yang sering dipicu oleh stres atau tekanan (seperti mahasiswa tingkat akhir).",
  "follow_up_questions": [
    "Apakah ada gejala lain yang dirasakan selain susah tidur, tidak fokus, dan gampang emosi, misalnya jantung berdebar, napas pendek, merasa sangat sedih/putus asa, atau pikiran untuk menyakiti diri sendiri?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Kondisi pasien memengaruhi fungsi harian dan kualitas hidup namun tidak menunjukkan gejala yang mengancam jiwa atau memerlukan penanganan darurat. Namun, kurang tidur yang berkepanjangan dapat berdampak buruk pada kesehatan fisik dan mental serta performa akademik, sehingga memerlukan evaluasi dan penanganan medis lebih lanjut."
}

{
  "diagnosis": "Demam Dengue (Dengue Fever)",
  "diagnosis_reasoning": "Kombinasi demam tinggi, sakit kepala, nyeri otot dan sendi di seluruh badan, dan terutama nyeri di belakang bola mata yang dialami selama 2 hari, sangat karakteristik untuk demam dengue, apalagi terjadi di musim hujan.",
  "follow_up_questions": [
    "Apakah Anda mengalami mual, muntah, atau muncul ruam kulit/bintik merah di tubuh?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala yang mengarah kuat ke demam dengue dengan demam tinggi selama 2 hari memerlukan evaluasi medis segera dan pemantauan untuk mencegah potensi komplikasi, meskipun saat ini belum ada tanda-tanda kegawatdaruratan."
}

{
  "diagnosis": "Anemia (kemungkinan besar Anemia Defisiensi Besi)",
  "diagnosis_reasoning": "Gejala pusing, mudah lelah, kulit pucat, dan jantung berdebar-debar sangat konsisten dengan tanda-tanda anemia, di mana tubuh kekurangan sel darah merah atau hemoglobin yang cukup untuk membawa oksigen ke jaringan. Anemia defisiensi besi adalah jenis anemia yang paling umum, terutama pada wanita usia subur.",
  "follow_up_questions": [
    "Apakah Anda mengalami menstruasi yang berat atau berkepanjangan?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala yang dialami bersifat kronis dan memengaruhi kualitas hidup, namun tidak menunjukkan kondisi darurat medis yang memerlukan penanganan segera di UGD. Diperlukan evaluasi medis oleh dokter untuk konfirmasi diagnosis dan penanganan yang tepat."
}

{
  "diagnosis": "Infeksi Saluran Kemih (ISK) bagian bawah / Sistitis",
  "diagnosis_reasoning": "Gejala sering buang air kecil, nyeri dan perih saat berkemih (disuria), serta nyeri di perut bagian bawah sangat khas untuk infeksi saluran kemih bagian bawah.",
  "follow_up_questions": [
    "Apakah Anda juga merasakan demam, menggigil, atau nyeri di punggung bagian samping (area pinggang)?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala menunjukkan adanya infeksi yang memerlukan pemeriksaan dan penanganan medis untuk mencegah komplikasi atau penyebaran infeksi ke ginjal."
}

{
  "diagnosis": "Gastritis atau Dugaan Ulkus Peptikum",
  "diagnosis_reasoning": "Nyeri perih seperti ditusuk-tusuk di perut kiri atas, mual, kembung selama 3 hari, riwayat telat makan, dan antasida yang biasanya efektif kini tidak mempan, sangat mengarah pada iritasi atau peradangan lambung yang signifikan, kemungkinan gastritis atau ulkus peptikum.",
  "follow_up_questions": [
    "Apakah ada demam, penurunan berat badan yang tidak disengaja, atau perubahan pada pola buang air besar, seperti feses berwarna hitam gelap atau seperti aspal?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala nyeri perut kiri atas yang menetap, perih seperti ditusuk-tusuk, tidak membaik dengan antasida, dan berlangsung selama 3 hari menunjukkan kondisi yang memerlukan pemeriksaan medis untuk diagnosis pasti dan penanganan yang tepat, serta untuk menyingkirkan komplikasi seperti ulkus yang lebih serius."
}

{
  "diagnosis": "Vertigo Posisi Paroksismal Benigna (BPPV)",
  "diagnosis_reasoning": "Gejala pusing berputar hebat yang mendadak saat bangun tidur, berlangsung singkat (beberapa detik), berulang beberapa kali dalam sehari, dan menyebabkan sensasi jatuh, sangat konsisten dengan Vertigo Posisi Paroksismal Benigna (BPPV). Tidak ada gejala lain yang mengindikasikan stroke pada laporan awal.",
  "follow_up_questions": [
    "Apakah Anda mengalami gejala lain yang menyertai pusing berputar ini, seperti mual, muntah, telinga berdenging, gangguan pendengaran, sakit kepala hebat, pandangan ganda, kesulitan bicara, atau kelemahan/mati rasa pada bagian tubuh?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Meskipun gejala paling mungkin disebabkan oleh kondisi yang tidak berbahaya (BPPV), intensitas pusing yang menyebabkan sensasi jatuh dan kekhawatiran pasien akan stroke memerlukan evaluasi medis. Dokter perlu melakukan pemeriksaan fisik untuk mengonfirmasi diagnosis, menyingkirkan penyebab yang lebih serius (seperti stroke), dan memberikan penanganan yang tepat."
}

{
  "diagnosis": "Hipoglikemia",
  "diagnosis_reasoning": "Kombinasi riwayat diabetes yang minum obat dan belum sarapan dengan gejala berkeringat dingin, gemetar, serta pandangan kabur sangat mengindikasikan kadar gula darah yang terlalu rendah.",
  "follow_up_questions": [
    "Apakah Anda memiliki alat cek gula darah di rumah dan sudahkah Anda memeriksa kadar gula darah Anda saat ini?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Gejala hipoglikemia memerlukan penanganan segera untuk mencegah komplikasi serius. Meskipun belum darurat berat (misalnya, hilang kesadaran), kondisi ini dapat memburuk dengan cepat jika tidak ditangani."
}

{
  "diagnosis": "Dermatitis Kontak Akut",
  "diagnosis_reasoning": "Gejala gatal, kemerahan, dan bentol-bentol kecil berair pada tangan yang muncul setelah menggunakan sabun cuci piring merek baru sangat konsisten dengan reaksi peradangan kulit akibat kontak langsung dengan zat iritan atau alergen.",
  "follow_up_questions": [
    "Apakah ada bagian tubuh lain selain tangan yang juga mengalami gejala serupa?"
  ],
  "triage": "rendah",
  "triage_reasoning": "Gejala yang terlokalisasi pada tangan dan karakteristik dermatitis kontak umumnya tidak mengancam jiwa dan dapat ditangani dengan menghindari pemicu serta perawatan kulit lokal. Tidak ada indikasi reaksi sistemik serius atau infeksi sekunder yang berat pada tahap ini."
}

{
  "diagnosis": "Pertussis (Batuk Rejan)",
  "diagnosis_reasoning": "Gejala batuk parah yang berlangsung 2 minggu, disertai bunyi 'hup' keras saat menarik napas, terutama memburuk di malam hari, sangat khas untuk pertussis.",
  "follow_up_questions": [
    "Apakah anak Anda mengalami muntah atau kebiruan setelah batuk, atau kesulitan bernapas di antara episode batuk?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Batuk dengan karakteristik 'whooping cough' (bunyi 'hup') memerlukan evaluasi medis segera karena dugaan pertussis, suatu infeksi bakteri yang menular dan berpotensi serius, meskipun pada usia 6 tahun risikonya lebih rendah dibandingkan bayi. Diagnosis dan penanganan dini penting untuk mencegah komplikasi dan penularan."
}

{
  "diagnosis": "Dugaan Demam Tifoid",
  "diagnosis_reasoning": "Demam berkepanjangan selama seminggu dengan pola peningkatan suhu di sore/malam hari, nyeri perut kiri, lemas, dan penurunan nafsu makan drastis, ditambah dengan riwayat konsumsi makanan di kantin kampus (faktor risiko), sangat sesuai dengan gambaran klinis Demam Tifoid. Nyeri perut kiri dapat mengindikasikan splenomegali atau peradangan usus.",
  "follow_up_questions": [
    "Apakah Anda mengalami diare atau sembelit selama seminggu terakhir ini, dan bagaimana karakteristiknya (misalnya frekuensi atau konsistensi tinja)?"
  ],
  "triage": "menengah",
  "triage_reasoning": "Pasien mengalami demam yang sudah berlangsung satu minggu disertai gejala sistemik (lemas, nafsu makan turun drastis) dan nyeri perut, yang memerlukan evaluasi medis segera untuk penegakan diagnosis dan tatalaksana yang tepat guna mencegah komplikasi serius yang dapat terjadi jika kondisi tidak ditangani."
}
